{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret angiver de tre centrale betingelser (almindelige SU/slutlån-betingelser, videregående uddannelse eller dansk EUD, varig funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen) i overensstemmelse med rubrikken og vejledningen. Ingen af rubrikkens væsentlige fejl findes. Afsnittet om ret til SU og indskrivning svarer til vejledningens afsnit 3.2.1."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element kræver også, at handicaptillægget udbetales sammen med SU-stipendium eller slutlån. Det fremgår ikke eksplicit; svaret siger kun, at de almindelige SU/slutlån-betingelser skal opfyldes, og at man skal have ret til SU. De to andre kritiske elementer er dækket."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte spørgsmålet om betingelserne og opstiller dem punktvist uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret henviser ikke til nogen identificerbar kilde som lov, bestemmelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle udsagn kan genfindes i de udleverede kilder (vejledningens afsnit 3.1, 3.2.1 og 3.3 samt SU-lovens § 7, stk. 3). Svaret tilføjer ingen ny regel, undtagelse eller tærskel."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Rubrikken kræver kun et overblik uden standardadvarsel. Svaret bevarer 'varig' og 'meget betydelige begrænsninger'. Den præcisering af SU-betingelserne, svaret giver, er ikke i strid med kilden."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Opstillingen er intern sammenhængende. Afslutningen om ret til SU og indskrivning gentager og uddyber punkt 1 uden at modsige noget."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal' bruges om betingelserne, hvilket svarer til vejledningens 'for at få handicaptillæg skal ... opfylde'. Der gøres ikke skøn eller undtagelser absolutte."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "yes",
      "reason": "Punkt 1 gengiver, at de almindelige betingelser for SU eller slutlån skal opfyldes."
    },
    "A2": {
      "label": "partial",
      "reason": "Svaret nævner kravet om en videregående uddannelse eller dansk EUD, men ikke at EUD omfatter EUX eller at erhvervslignende uddannelse i udlandet ikke er omfattet. Svaret siger 'gå på', men ikke udtrykkeligt 'indskrevet på'."
    },
    "A3": {
      "label": "yes",
      "reason": "Punkt 3 gengiver næsten ordret kravet om varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen."
    },
    "A4": {
      "label": "yes",
      "reason": "Svaret angiver, at man skal have ret til SU og være indskrevet på og gennemgå en uddannelse, der berettiger til SU eller slutlån."
    },
    "A6": {
      "label": "no",
      "reason": "Svaret nævner hverken EUX eller afgrænsningen mod erhvervslignende uddannelse uden for Danmark. Det nævner kun EUD generelt."
    }
  },
  "overall_notes": "Indholdsmæssigt korrekt overblik over de tre betingelser, men uden kildeangivelse (C04 not_met, C05 og C06 not_assessable). Det mangler også, at tillægget udbetales sammen med SU-stipendium eller slutlån (C02 not_met), og supporting-elementerne om EUX og udlandet er udeladt."
}

